// ============================================================================
// KRATOS FSAE — DECODIFICADOR DE TRAMAS CAN BUS (FORMATO BIG ENDIAN / MOTOROLA)
// ============================================================================
// Salida 1: Objeto estructurado para InfluxDB (nodo influxdb out)
// Salida 2: Mensajes MQTT jerárquicos (kratos/telemetria/...)
// Salida 3: Line Protocol directo a InfluxDB v2 API (garantiza escritura 0-config)

const payload = msg.payload || {};
const canId = (payload.canid !== undefined) ? payload.canid : msg.canid;
const rawData = payload.data || msg.data;

if (canId === undefined || !rawData) {
    return null;
}

const buf = Buffer.isBuffer(rawData) ? rawData : Buffer.from(rawData);
if (buf.length < 8) {
    return null;
}

const timestampMs = Date.now();
let measurement = null;
let fields = {};
let tags = {
    source: "can_bus",
    hex_id: "0x" + canId.toString(16).toUpperCase()
};
let mqttMessages = [];

// ----------------------------------------------------------------------------
// 1. ID 0x10D (269 dec): Energy Meter — Voltaje y Corriente
//    Bytes 0..1: uint16 BE -> Voltaje (factor 0.1 V, ej: 3500 = 350.0 V)
//    Bytes 2..3: int16 BE  -> Corriente (factor 0.1 A, ej: 850 = 85.0 A)
//    Bytes 4..7: int32 BE  -> Potencia instantánea (W)
// ----------------------------------------------------------------------------
if (canId === 0x10D) {
    const voltaje = Number((buf.readUInt16BE(0) * 0.1).toFixed(2));
    const corriente = Number((buf.readInt16BE(2) * 0.1).toFixed(2));
    const potencia = buf.readInt32BE(4);

    measurement = "energy_meter";
    tags.subsystem = "energy_meter";
    fields = {
        voltaje: voltaje,
        corriente: corriente,
        potencia: potencia
    };

    mqttMessages.push(
        { topic: "kratos/telemetria/energy_meter/voltaje", payload: voltaje, qos: 0, retain: false },
        { topic: "kratos/telemetria/energy_meter/corriente", payload: corriente, qos: 0, retain: false },
        { topic: "kratos/telemetria/energy_meter/potencia", payload: potencia, qos: 0, retain: false },
        { topic: "kratos/telemetria/energy_meter/resumen", payload: { voltaje, corriente, potencia, timestamp: timestampMs }, qos: 0, retain: false }
    );
}

// ----------------------------------------------------------------------------
// 2. ID 0x40D (1037 dec): Energy Meter — Estado y Energía Acumulada
//    Bytes 0..3: uint32 BE -> Energía acumulada (factor 0.1 Wh)
//    Byte  4:    uint8     -> Código de estado (0 = OK, 1 = WARN, 2 = FAULT)
//    Bytes 5..6: uint16 BE -> Contador de tramas / diagnóstico
// ----------------------------------------------------------------------------
else if (canId === 0x40D) {
    const energiaWh = Number((buf.readUInt32BE(0) * 0.1).toFixed(2));
    const estadoCodigo = buf.readUInt8(4);
    const contador = buf.readUInt16BE(5);

    measurement = "energy_meter_status";
    tags.subsystem = "energy_meter";
    fields = {
        energia_wh: energiaWh,
        estado: estadoCodigo,
        contador_tramas: contador
    };

    mqttMessages.push(
        { topic: "kratos/telemetria/energy_meter/energia", payload: energiaWh, qos: 0, retain: false },
        { topic: "kratos/telemetria/energy_meter/estado", payload: estadoCodigo, qos: 0, retain: false }
    );
}

// ----------------------------------------------------------------------------
// 3. ID 0x6B0 (1712 dec) / 0x6B1 (1713 dec): Orion BMS — Voltaje Pack, SOC y Temperaturas
//    Bytes 0..1: uint16 BE -> Voltaje Pack BMS (factor 0.1 V)
//    Bytes 2..3: int16 BE  -> Corriente Pack BMS (factor 0.1 A)
//    Byte  4:    uint8     -> Estado de Carga SOC (factor 0.5 %)
//    Byte  5:    int8      -> Temperatura Máxima de Celdas (°C)
//    Byte  6:    int8      -> Temperatura Promedio de Celdas (°C)
//    Byte  7:    uint8     -> Flags de Estado BMS
// ----------------------------------------------------------------------------
else if (canId === 0x6B0 || canId === 0x6B1) {
    const voltajePack = Number((buf.readUInt16BE(0) * 0.1).toFixed(2));
    const corrientePack = Number((buf.readInt16BE(2) * 0.1).toFixed(2));
    const soc = Number((buf.readUInt8(4) * 0.5).toFixed(1));
    const tempMax = buf.readInt8(5);
    const tempPromedio = buf.readInt8(6);
    const estadoBms = buf.readUInt8(7);

    measurement = "orion_bms";
    tags.subsystem = "bms";
    fields = {
        voltaje_pack: voltajePack,
        corriente_pack: corrientePack,
        soc: soc,
        temperatura_max: tempMax,
        temperatura_promedio: tempPromedio,
        estado_bms: estadoBms
    };

    mqttMessages.push(
        { topic: "kratos/telemetria/bms/voltaje_pack", payload: voltajePack, qos: 0, retain: false },
        { topic: "kratos/telemetria/bms/corriente_pack", payload: corrientePack, qos: 0, retain: false },
        { topic: "kratos/telemetria/bms/soc", payload: soc, qos: 0, retain: false },
        { topic: "kratos/telemetria/bms/temperatura", payload: tempMax, qos: 0, retain: false },
        { topic: "kratos/telemetria/bms/temperatura_promedio", payload: tempPromedio, qos: 0, retain: false },
        { topic: "kratos/telemetria/bms/resumen", payload: { voltajePack, corrientePack, soc, tempMax, tempPromedio, estadoBms, timestamp: timestampMs }, qos: 0, retain: false }
    );
} else {
    // Trama CAN no registrada en el filtro de telemetría principal
    return null;
}

// Preparar Salida 1: Formato para nodo influxdb out
const influxNodeMsg = {
    measurement: measurement,
    payload: [
        fields,
        tags
    ]
};

// Preparar Salida 3: Line Protocol vía HTTP API InfluxDB v2 usando variables de entorno
const tagStr = Object.entries(tags).map(([k, v]) => `${k}=${v}`).join(",");
const fieldStr = Object.entries(fields).map(([k, v]) => `${k}=${v}`).join(",");
const lineProtocol = `${measurement},${tagStr} ${fieldStr} ${timestampMs}`;
const baseUrl = env.get("INFLUXDB_URL") || "http://influxdb:8086";
const token = env.get("INFLUXDB_TOKEN") || "kratos-fsae-telemetry-token-2026";
const org = env.get("INFLUXDB_ORG") || "kratos_fsae";
const bucket = env.get("INFLUXDB_BUCKET") || "telemetria_carro";

const influxHttpMsg = {
    method: "POST",
    url: `${baseUrl}/api/v2/write?org=${encodeURIComponent(org)}&bucket=${encodeURIComponent(bucket)}&precision=ms`,
    headers: {
        "Authorization": `Token ${token}`,
        "Content-Type": "text/plain; charset=utf-8"
    },
    payload: lineProtocol
};

return [influxNodeMsg, [mqttMessages], influxHttpMsg];
